UserController<pre contenteditable="false" data-code="@RestController
@RequestMapping(&quot;/users&quot;)
class UserController {
    @GetMapping
    List&lt;User&gt; list() { return userRepository.findAll(); }

    @GetMapping(&quot;/{id}&quot;)
    User show(@PathVariable long id) {
        return userRepository.findById(id);
    }
}" data-lang="javascript" style="background-color: rgb(30, 31, 46); color: rgb(248, 248, 242); padding: 28px 32px; border-radius: 12px; font-family: Consolas, Monaco, &quot;Courier New&quot;, monospace; font-size: 15px; overflow-x: auto; margin: 24px 0px; white-space: pre; line-height: 1.3; tab-size: 4;">@RestController
@RequestMapping("/users")
class UserController {
    @GetMapping
    List&lt;User&gt; list() { return userRepository.findAll(); }

    @GetMapping("/{id}")
    User show(@PathVariable long id) {
        return userRepository.findById(id);
    }
}</pre>

